package vn.btl.teaching;
import java.util.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class WebController {
 private final Queries q;private final BusinessService business;private final Identity identity;private final CatalogService catalog;
 public WebController(Queries q,BusinessService b,Identity i,CatalogService c){this.q=q;business=b;identity=i;catalog=c;}
 @GetMapping("/login") String login(){return "login";}
 @GetMapping("/forbidden") String forbidden(jakarta.servlet.http.HttpServletResponse r){r.setStatus(403);return "forbidden";}
 private long filters(Long sem,String search,Model m){long s=sem==null?q.defaultSemester():sem;m.addAttribute("semesters",q.semesters());m.addAttribute("semester",s);m.addAttribute("search",search==null?"":search);return s;}
 @GetMapping("/") String home(@AuthenticationPrincipal AppUser u,Model m){long s=filters(null,"",m);m.addAttribute("title","Tổng quan");m.addAttribute("sections",q.sections(u,s,""));m.addAttribute("grades",q.grades(u,s));if(!u.getRole().equals("LECTURER"))m.addAttribute("tuition",q.tuition(u,s,""));return "home";}
 @GetMapping("/sections") String sections(@AuthenticationPrincipal AppUser u,@RequestParam(required=false) Long semester,@RequestParam(defaultValue="") String search,Model m){long s=filters(semester,search,m);m.addAttribute("title",u.getRole().equals("LECTURER")?"Lớp phụ trách":"Lớp học phần");m.addAttribute("rows",q.sections(u,s,search));if(u.getRole().equals("STUDENT")){var enrolled=q.enrollments(u,s);m.addAttribute("enrollments",enrolled);m.addAttribute("registeredCodes",enrolled.stream().filter(e->"ACTIVE".equals(e.get("status"))).map(e->e.get("code").toString()).toList());}return "sections";}
 @GetMapping("/sections/{id}/roster") String roster(@AuthenticationPrincipal AppUser u,@PathVariable long id,Model m){m.addAttribute("title","Danh sách sinh viên");m.addAttribute("rows",q.roster(u,id));return "roster";}
 @PostMapping("/student/register") String register(@AuthenticationPrincipal AppUser u,@RequestParam long sectionId,@RequestParam long semester,RedirectAttributes a){try{business.register(u,sectionId);a.addFlashAttribute("success","Đăng ký học phần thành công.");}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));}return "redirect:/sections?semester="+semester;}
 @PostMapping("/student/cancel") String cancel(@AuthenticationPrincipal AppUser u,@RequestParam long enrollmentId,@RequestParam long semester,RedirectAttributes a){try{business.cancel(u,enrollmentId);a.addFlashAttribute("success","Đã hủy đăng ký. Bạn có thể kiểm tra lại công nợ.");}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));}return "redirect:/sections?semester="+semester;}
 @GetMapping("/grades") String grades(@AuthenticationPrincipal AppUser u,@RequestParam(required=false) Long semester,Model m){long s=filters(semester,"",m);m.addAttribute("title","Kết quả học tập");m.addAttribute("rows",q.grades(u,s));return "grades";}
 @GetMapping("/lecturer/scores/{id}") String scores(@AuthenticationPrincipal AppUser u,@PathVariable long id,@RequestParam long semester,Model m){var r=q.grades(u,semester).stream().filter(x->((Number)x.get("enrollment_id")).longValue()==id).findFirst().orElseThrow(()->new org.springframework.security.access.AccessDeniedException("Bạn không được nhập điểm cho đăng ký này."));m.addAttribute("row",r);m.addAttribute("semester",semester);m.addAttribute("title","Nhập điểm sinh viên");return "scores";}
 @PostMapping("/lecturer/scores/{id}") String saveScores(@AuthenticationPrincipal AppUser u,@PathVariable long id,@RequestParam long semester,@RequestParam Map<String,String> f,RedirectAttributes a){try{business.scores(u,id,f);a.addFlashAttribute("success","Đã lưu điểm và cập nhật kết quả học tập.");return "redirect:/grades?semester="+semester;}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));a.addFlashAttribute("attempt",f);return "redirect:/lecturer/scores/"+id+"?semester="+semester;}}
 @GetMapping("/schedule") String schedule(@AuthenticationPrincipal AppUser u,@RequestParam(required=false) Long semester,Model m){long s=filters(semester,"",m);m.addAttribute("title","Lịch học trong tuần");m.addAttribute("rows",q.schedules(u,s));return "schedule";}
 @GetMapping("/tuition") String tuition(@AuthenticationPrincipal AppUser u,@RequestParam(required=false) Long semester,@RequestParam(defaultValue="") String search,Model m){long s=filters(semester,search,m);m.addAttribute("title","Học phí & công nợ");m.addAttribute("rows",q.tuition(u,s,search));if(u.isManager()){m.addAttribute("students",q.students());m.addAttribute("receipt", "PT-"+java.util.UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase());}return "tuition";}
 @PostMapping("/payments/record") String payment(@AuthenticationPrincipal AppUser u,@RequestParam Map<String,String> f,RedirectAttributes a){long sem=Input.id(f,"semester_id");try{a.addFlashAttribute("success",business.payment(u,f));}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));a.addFlashAttribute("attempt",f);}return "redirect:/tuition?semester="+sem;}
 @GetMapping("/payments") String payments(@AuthenticationPrincipal AppUser u,@RequestParam(required=false) Long semester,Model m){long s=filters(semester,"",m);m.addAttribute("title","Lịch sử phiếu thu");m.addAttribute("rows",q.payments(u,s));return "payments";}
 @GetMapping("/manage") String manage(Model m){m.addAttribute("title","Quản lý danh mục");m.addAttribute("catalogs",catalog.titles());return "manage";}
 @GetMapping("/manage/accounts") String accounts(@AuthenticationPrincipal AppUser u,Model m){m.addAttribute("title","Tài khoản truy cập");m.addAttribute("rows",catalog.accounts(u));return "accounts";}
 @PostMapping("/manage/accounts/{id}/toggle") String toggle(@AuthenticationPrincipal AppUser u,@PathVariable long id,RedirectAttributes a){try{catalog.toggle(u,id);a.addFlashAttribute("success","Đã cập nhật trạng thái tài khoản.");}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));}return "redirect:/manage/accounts";}
 @PostMapping("/manage/accounts/{id}/password") String reset(@AuthenticationPrincipal AppUser u,@PathVariable long id,@RequestParam String password,RedirectAttributes a){try{catalog.reset(u,id,password);a.addFlashAttribute("success","Đã đặt lại mật khẩu.");}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));}return "redirect:/manage/accounts";}
 @GetMapping("/manage/{kind}") String catalog(@PathVariable String kind,Model m){m.addAttribute("title",catalog.title(kind));m.addAttribute("kind",kind);m.addAttribute("fields",catalog.fields(kind,false));m.addAttribute("rows",catalog.list(kind));return "catalog";}
 private String form(String kind,Long id,Model m,Map<String,?> values){m.addAttribute("title",(id==null?"Thêm ":"Chỉnh sửa ")+catalog.title(kind).toLowerCase());m.addAttribute("kind",kind);m.addAttribute("id",id);m.addAttribute("fields",catalog.fields(kind,id==null));m.addAttribute("values",values);return "catalog-form";}
 @GetMapping("/manage/{kind}/new") String create(@PathVariable String kind,Model m){return form(kind,null,m,Map.of());}
 @GetMapping("/manage/{kind}/{id}/edit") String edit(@PathVariable String kind,@PathVariable long id,Model m){return form(kind,id,m,catalog.row(kind,id));}
 @PostMapping("/manage/{kind}/save") String save(@AuthenticationPrincipal AppUser u,@PathVariable String kind,@RequestParam(required=false) Long id,@RequestParam Map<String,String> f,Model m,RedirectAttributes a){try{catalog.save(u,kind,id,f);a.addFlashAttribute("success","Đã lưu dữ liệu thành công.");return "redirect:/manage/"+kind;}catch(Exception e){m.addAttribute("error",Errors.message(e));var safe=new HashMap<>(f);safe.remove("password");return form(kind,id,m,safe);}}
 @PostMapping("/manage/{kind}/{id}/delete") String delete(@AuthenticationPrincipal AppUser u,@PathVariable String kind,@PathVariable long id,RedirectAttributes a){try{catalog.delete(u,kind,id);a.addFlashAttribute("success","Đã xóa bản ghi.");}catch(Exception e){a.addFlashAttribute("error",Errors.message(e));}return "redirect:/manage/"+kind;}
}
